```go
package main

import (
    "fmt"
    "os"
)

func size(name string) (int64, error) {
    file, err := os.Open(name)
    if err != nil { return 0, err }
    defer file.Close()

    info, err := file.Stat()
    if err != nil { return 0, err }
    return info.Size(), nil
}

func main() {
    n, err := size(os.Args[0])
    fmt.Println(n > 0, err)
}
```
The executable file is closed whether `Stat` succeeds or returns early with an error. The program prints `true <nil>` in a normal run.

```go
package main

import (
    "fmt"
    "os"
)

func inspect(name string) error {
    file, err := os.Open(name)
    if err != nil { return err }
    defer file.Close()
    _, err = file.Stat()
    return err
}

func main() {
    for _, name := range os.Args[:1] {
        fmt.Println(inspect(name))
    }
}
```
`inspect` returns once per file, so its deferred close runs before the next iteration. In this sample it prints `<nil>` for the executable path.

```go
package main

import "fmt"

func trace(include bool) {
    defer fmt.Println("A")
    if include {
        defer fmt.Println("B")
    }
    for i := 0; i < 2; i++ {
        defer fmt.Println(i)
    }
    fmt.Println("body")
}

func main() { trace(true) }
```
The output is `body`, `1`, `0`, `B`, `A`. The loop registers two calls with argument snapshots, and the true branch contributes `B`.
